  "sample_size": 9,
  "provenance": {
    "sql": "SELECT repository, SUM(insertions + deletions) AS value, COUNT(*) AS n FROM (\n        SELECT DISTINCT c.id, c.repository_id AS repository, c.insertions, c.deletions, c.committed_at,\n               c.is_merge, r.workspace_id AS ws\n        FROM task_commits c JOIN repositories r ON r.id = c.repository_id\n    ) WHERE ws = ? AND (NOT is_merge) GROUP BY repository ORDER BY repository LIMIT 500",
    "source": "DuckDB snapshot of the SQLite database",
    "generated_at": "<ts:38|db>"
  },
  "notes": [
    "Metrics describe observed associations; differences between groups do not establish causation."
  ]
}

